package com.kidverse.app;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.Toast;import org.json.*;import java.io.*;import java.net.*;
public final class UpdateManager {
 private static final String API="https://api.github.com/repos/rautshivamxyz-beep/KIDVERSE/releases/latest", PREF="kidverse_updates";
 private UpdateManager(){}
 public static void checkForUpdate(Activity a,boolean manual){new Thread(()->{HttpURLConnection c=null;try{
 c=(HttpURLConnection)new URL(API).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","KIDVERSE-Android");if(c.getResponseCode()!=200)throw new Exception();
 StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()))){String l;while((l=r.readLine())!=null)b.append(l);}
 JSONObject release=new JSONObject(b.toString());String tag=release.optString("tag_name","");int code=toCode(tag);JSONArray assets=release.optJSONArray("assets");String apk=null;if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject x=assets.getJSONObject(i);if("KIDVERSE.apk".equals(x.optString("name")))apk=x.optString("browser_download_url",null);}
 final String url=apk,name=release.optString("name",tag);if(code>BuildConfig.VERSION_CODE&&url!=null&&url.startsWith("https://github.com/"))a.runOnUiThread(()->{if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("KIDVERSE update available").setMessage(name+" is ready. Download it? Your saved progress stays on this device.").setNegativeButton("Later",null).setPositiveButton("Download",(d,w)->download(a,url)).show();});
 else if(manual)a.runOnUiThread(()->Toast.makeText(a,"KIDVERSE is up to date.",Toast.LENGTH_LONG).show());
 }catch(Exception e){if(manual)a.runOnUiThread(()->Toast.makeText(a,"Update check failed. Try again when online.",Toast.LENGTH_LONG).show());}finally{if(c!=null)c.disconnect();}}).start();}
 private static int toCode(String t){try{String[]p=(t.startsWith("v")?t.substring(1):t).split("\\.");return Integer.parseInt(p[0])*10000+(p.length>1?Integer.parseInt(p[1])*100:0)+(p.length>2?Integer.parseInt(p[2].replaceAll("[^0-9].*$","")):0);}catch(Exception e){return -1;}}
 private static void download(Activity a,String url){try{DownloadManager m=(DownloadManager)a.getSystemService(Context.DOWNLOAD_SERVICE);DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setTitle("KIDVERSE update");r.setDescription("Downloading latest version");r.setMimeType("application/vnd.android.package-archive");r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalFilesDir(a,Environment.DIRECTORY_DOWNLOADS,"KIDVERSE-update.apk");long id=m.enqueue(r);a.getSharedPreferences(PREF,0).edit().putLong("id",id).apply();Toast.makeText(a,"Downloading. When finished, open Parent Zone and tap Install downloaded update.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(a,"Download could not start.",Toast.LENGTH_LONG).show();}}
 public static void installPending(Activity a){long id=a.getSharedPreferences(PREF,0).getLong("id",-1);if(id<0){Toast.makeText(a,"No downloaded update found.",0).show();return;}DownloadManager m=(DownloadManager)a.getSystemService(Context.DOWNLOAD_SERVICE);try(Cursor c=m.query(new DownloadManager.Query().setFilterById(id))){if(c==null||!c.moveToFirst()||c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))!=DownloadManager.STATUS_SUCCESSFUL){Toast.makeText(a,"Update is not downloaded yet.",0).show();return;}Uri u=m.getUriForDownloadedFile(id);if(u==null)throw new Exception();if(Build.VERSION.SDK_INT>=26&&!a.getPackageManager().canRequestPackageInstalls()){a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));Toast.makeText(a,"Allow KIDVERSE to install updates, return and tap Install downloaded update.",Toast.LENGTH_LONG).show();return;}Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(u,"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_ACTIVITY_NEW_TASK);a.startActivity(i);}catch(Exception e){Toast.makeText(a,"Could not open installer. Download again.",Toast.LENGTH_LONG).show();}}
}